using System.Windows;
using System.Windows.Media;
using VisionFramework;
namespace VisionUi;
public static class RoiWpfGeometry {
 public static bool IsBox(RoiKind k)=>k is RoiKind.Rectangle or RoiKind.UprightRectangle or RoiKind.LineBox or RoiKind.SequentialBox or RoiKind.PolygonCaliper or RoiKind.MatrixCircle;
 public static bool IsLine(RoiKind k)=>k is RoiKind.Line or RoiKind.LineCaliper or RoiKind.SectorCaliper;
 public static bool IsRadial(RoiKind k)=>k is RoiKind.Circle or RoiKind.Annulus or RoiKind.SectorRing or RoiKind.Sector or RoiKind.OverSector or RoiKind.CircleCaliper;
 public static (Point Center,double Start,double Sweep) SectorArc(RoiDocument r){var s=RoiGeometry.Parameters(r);double dx=s.EndX-r.CenterX,dy=s.EndY-r.CenterY,chord=Math.Sqrt(dx*dx+dy*dy),radius=Math.Max(r.Radius,chord/2);double px=chord==0?-1:-dy/chord,py=chord==0?0:dx/chord;double sign=s.IsLargeArc==s.IsClockwise?-1:1;double distance=Math.Sqrt(Math.Max(0,radius*radius-chord*chord/4));var center=new Point((r.CenterX+s.EndX)/2+px*distance*sign,(r.CenterY+s.EndY)/2+py*distance*sign);double minor=2*Math.Asin(Math.Clamp(chord/(2*radius),0,1))*180/Math.PI;return(center,Math.Atan2(r.CenterY-center.Y,r.CenterX-center.X)*180/Math.PI,(s.IsClockwise?1:-1)*(s.IsLargeArc?360-minor:minor));}
 public static (Point Center,double Angle) ActiveCaliper(RoiDocument r){var s=RoiGeometry.Parameters(r);if(r.Kind==RoiKind.LineCaliper){double i=Math.Ceiling(s.CaliperCount/2.0);return(new(r.CenterX+(s.EndX-r.CenterX)*i/(s.CaliperCount+1),r.CenterY+(s.EndY-r.CenterY)*i/(s.CaliperCount+1)),Math.Atan2(s.EndY-r.CenterY,s.EndX-r.CenterX)*180/Math.PI);}if(r.Kind==RoiKind.CircleCaliper){double step=360.0/s.CaliperCount,index=Math.Ceiling(s.CaliperCount*3/4.0-s.StartAngle/step);double angle=step*(Math.Clamp(index,1,s.CaliperCount)-.5)+s.StartAngle;return(Polar(new(r.CenterX,r.CenterY),r.Radius,angle),angle+90);}var arc=SectorArc(r);double a=arc.Start+arc.Sweep*(s.CaliperCount/2+.5)/s.CaliperCount;return(Polar(arc.Center,r.Radius,a),a+90);}
 public static IReadOnlyList<Point> CaliperHandles(RoiDocument r){var s=RoiGeometry.Parameters(r);var c=ActiveCaliper(r);double a=c.Angle*Math.PI/180;var x=new Vector(Math.Cos(a),Math.Sin(a));var y=new Vector(-Math.Sin(a),Math.Cos(a));return [c.Center+x*s.CaliperWidth/2,c.Center+y*s.CaliperHeight/2,c.Center+x*s.CaliperWidth/2+y*s.CaliperHeight/2];}
 public static Geometry Create(RoiDocument r){var s=RoiGeometry.Parameters(r);if(r.Kind==RoiKind.Box3D||r.Kind==RoiKind.FullImage)return Geometry.Empty;
  if(IsBox(r.Kind)){var box=new RectangleGeometry(new Rect(r.CenterX-r.Width/2,r.CenterY-r.Height/2,r.Width,r.Height));box.Transform=new RotateTransform(r.AngleDegrees,r.CenterX,r.CenterY);if(r.Kind!=RoiKind.MatrixCircle)return box;var group=new GeometryGroup{FillRule=FillRule.Nonzero};group.Children.Add(box);foreach(var center in RoiGeometry.MatrixCenters(r)){group.Children.Add(new EllipseGeometry(new Point(center.X,center.Y),r.Radius,r.Radius));group.Children.Add(new EllipseGeometry(new Point(center.X,center.Y),r.InnerRadius,r.InnerRadius));}return group;}
  if(r.Kind==RoiKind.Polygon){var path=new StreamGeometry();using(var c=path.Open()){var points=r.Vertices??[];if(points.Count>0){c.BeginFigure(new Point(points[0].X,points[0].Y),true,true);c.PolyLineTo(points.Skip(1).Select(p=>new Point(p.X,p.Y)).ToArray(),true,false);}}return path;}
  if(r.Kind is RoiKind.Circle or RoiKind.CircleCaliper){var circle=new EllipseGeometry(new Point(r.CenterX,r.CenterY),r.Radius,r.Radius);if(r.Kind==RoiKind.Circle)return circle;var group=new GeometryGroup();group.Children.Add(circle);for(int i=0;i<s.CaliperCount;i++){double angle=s.StartAngle+360.0*(i+.5)/s.CaliperCount;double a=angle*Math.PI/180;group.Children.Add(Caliper(new Point(r.CenterX+r.Radius*Math.Cos(a),r.CenterY+r.Radius*Math.Sin(a)),s,angle+90));}return group;}
  if(r.Kind is RoiKind.SectorRing or RoiKind.Annulus)return new CombinedGeometry(GeometryCombineMode.Exclude,new EllipseGeometry(new Point(r.CenterX,r.CenterY),r.Radius,r.Radius),new EllipseGeometry(new Point(r.CenterX,r.CenterY),r.InnerRadius,r.InnerRadius));
  if(r.Kind is RoiKind.Sector or RoiKind.OverSector)return Sector(new(r.CenterX,r.CenterY),r.Radius,r.InnerRadius,s.StartAngle+r.AngleDegrees,s.SweepAngle);
  if(r.Kind==RoiKind.Point){var point=new GeometryGroup();point.Children.Add(new LineGeometry(new(r.CenterX-5,r.CenterY),new(r.CenterX+5,r.CenterY)));point.Children.Add(new LineGeometry(new(r.CenterX,r.CenterY-5),new(r.CenterX,r.CenterY+5)));return point;}
  if(r.Kind==RoiKind.Coordinate){var group=new GeometryGroup();var x=RoiGeometry.World(r,50,0);var y=RoiGeometry.World(r,0,50);group.Children.Add(new LineGeometry(new(r.CenterX,r.CenterY),new(x.X,x.Y)));group.Children.Add(new LineGeometry(new(r.CenterX,r.CenterY),new(y.X,y.Y)));return group;}
  if(IsLine(r.Kind)){var group=new GeometryGroup();if(r.Kind==RoiKind.SectorCaliper){var arc=SectorArc(r);group.Children.Add(Arc(arc.Center,r.Radius,arc.Start,arc.Sweep));for(int i=0;i<s.CaliperCount;i++){double angle=arc.Start+arc.Sweep*(i+.5)/s.CaliperCount;double a=angle*Math.PI/180;group.Children.Add(Caliper(new(arc.Center.X+r.Radius*Math.Cos(a),arc.Center.Y+r.Radius*Math.Sin(a)),s,angle+90));}}else{group.Children.Add(new LineGeometry(new(r.CenterX,r.CenterY),new(s.EndX,s.EndY)));if(r.Kind==RoiKind.LineCaliper){double angle=Math.Atan2(s.EndY-r.CenterY,s.EndX-r.CenterX)*180/Math.PI;for(int i=1;i<=s.CaliperCount;i++)group.Children.Add(Caliper(new(r.CenterX+(s.EndX-r.CenterX)*i/(s.CaliperCount+1),r.CenterY+(s.EndY-r.CenterY)*i/(s.CaliperCount+1)),s,angle));}}return group;}
  throw new NotSupportedException("尚未完成此类型的原生图形编辑："+r.Kind);
 }
 static Geometry Caliper(Point center,RoiShapeParameters s,double angle){var rect=new RectangleGeometry(new Rect(center.X-s.CaliperWidth/2,center.Y-s.CaliperHeight/2,s.CaliperWidth,s.CaliperHeight));rect.Transform=new RotateTransform(angle,center.X,center.Y);return rect;}
 public static Point Polar(Point center,double radius,double angle)=>new(center.X+radius*Math.Cos(angle*Math.PI/180),center.Y+radius*Math.Sin(angle*Math.PI/180));
 static Geometry Arc(Point center,double radius,double start,double sweep){var g=new StreamGeometry();using(var c=g.Open()){c.BeginFigure(Polar(center,radius,start),false,false);c.PolyLineTo(Enumerable.Range(1,181).Select(i=>Polar(center,radius,start+sweep*i/180)).ToArray(),true,false);}return g;}
 static Geometry Sector(Point center,double radius,double inner,double start,double sweep){var geometry=new StreamGeometry();using(var c=geometry.Open()){c.BeginFigure(Polar(center,radius,start),true,true);c.PolyLineTo(Enumerable.Range(1,180).Select(i=>Polar(center,radius,start+sweep*i/180)).ToArray(),true,false);c.PolyLineTo(Enumerable.Range(0,181).Select(i=>Polar(center,inner,start+sweep*(180-i)/180)).ToArray(),true,false);}return geometry;}
}
